import {quoteService} from './quote-service-config.js';
const form=document.querySelector('#quote-enquiry');
if(form){
 const $=s=>document.querySelector(s),email=$('#enquiry-email'),emailError=$('#enquiry-email-error'),error=$('#enquiry-error'),submit=$('#enquiry-submit');let pending=null,challenge=null,resendAt=0,timer;
 const endpoint=quoteService.endpoint.replace(/\/$/,'');const connected=!!endpoint&&new URL(endpoint,location.origin).protocol==='https:';
 function validateEmail(){email.value=email.value.trim();const ok=email.validity.valid&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value)&&!email.value.split('@')[0].includes('..')&&!email.value.split('@')[0].startsWith('.')&&!email.value.split('@')[0].endsWith('.')&&email.value.split('@')[1]?.split('.').every(label=>/^[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$/.test(label));email.setAttribute('aria-invalid',String(!ok));emailError.hidden=ok;emailError.textContent=ok?'':'Enter a complete email address, such as name@example.com.';return ok;}
 email.addEventListener('blur',()=>{if(email.value)validateEmail();});email.addEventListener('input',()=>{if(email.getAttribute('aria-invalid')==='true')validateEmail();});
 async function api(path,data){const response=await fetch(endpoint+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),credentials:'omit',signal:AbortSignal.timeout(15000)});let result;try{result=await response.json();}catch{throw Error('The email service is unavailable. Please try again or contact the showroom.');}if(!response.ok)throw Error(result.message||'We could not complete that request. Please try again.');return result;}
 function brief(data){return 'KABBY HOME — RENOVATION QUOTE ENQUIRY\n\nName: '+(data.name||'Not supplied')+'\nEmail: '+data.email+'\nRenovation timeline: '+data.timeline+'\nProject ZIP: '+(data.zip||'Not supplied')+'\n\nProject notes:\n'+(data.notes||'To discuss')+'\n\nDiscount-email preference: '+(data.discounts?'Yes — I give permission to receive Kabby Home discount information and cabinet planning updates by email. Please confirm signup and provide an opt-out method.':'No — please use my details only to respond to this enquiry.')+'\nConsent copy version: 2026-10-15\n\nThis is a renovation enquiry, not a cabinet configuration, placed order or payment. Email ownership has not been verified by this form.';}
 function manual(data){const text=brief(data),result=$('#enquiry-result');result.replaceChildren();const h=document.createElement('h2');h.textContent='Your enquiry is ready to review.';const p=document.createElement('p');p.textContent='It has not been sent. Open your email app, review the details, and send the message to Kabby Home.';const a=document.createElement('a');a.className='btn';a.href='mailto:info@amberleafhome.us?subject='+encodeURIComponent('Kabby Home — renovation quote enquiry')+'&body='+encodeURIComponent(text);a.textContent='Open Email to Kabby Home';const details=document.createElement('details'),summary=document.createElement('summary'),pre=document.createElement('pre');summary.textContent='Review your enquiry';pre.textContent=text;details.append(summary,pre);const download=document.createElement('button');download.type='button';download.className='btn outline';download.textContent='Download enquiry';download.onclick=()=>{const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='amber-leaf-quote-enquiry.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};result.append(h,p,a,download,details);result.hidden=false;h.tabIndex=-1;h.focus({preventScroll:true});}
 function cooldown(seconds){resendAt=Date.now()+Math.max(30,seconds||60)*1000;clearInterval(timer);const update=()=>{const remaining=Math.ceil((resendAt-Date.now())/1000);$('#enquiry-resend').disabled=remaining>0;$('#enquiry-resend').textContent=remaining>0?'Resend code in '+remaining+'s':'Resend code';if(remaining<=0)clearInterval(timer);};update();timer=setInterval(update,1000);}
 async function sendCode(){const result=await api('/start',pending);if(result.sent!==true||typeof result.challengeId!=='string')throw Error('Email delivery was not confirmed. Please try again later.');challenge=result.challengeId;form.hidden=true;$('#enquiry-verification').hidden=false;$('#verification-explanation').textContent='We sent a code to '+pending.email+'. Enter it to verify your email and send your renovation enquiry.';$('#enquiry-code').value='';$('#enquiry-code').focus();cooldown(result.retryAfter);}
 if(connected){submit.textContent='Send My Email Verification Code';$('#enquiry-delivery-note').textContent='We’ll email a verification code to confirm this address before submitting your enquiry. Discount emails are optional and only enabled if you opt in.';}
 form.addEventListener('submit',async e=>{e.preventDefault();error.hidden=true;if(!validateEmail()){email.focus();return;}if(!form.reportValidity())return;pending={name:form.elements.name.value.trim(),email:email.value,timeline:form.elements.timeline.value,zip:form.elements.zip.value.trim(),notes:form.elements.notes.value.trim(),discounts:form.elements.discounts.checked,consentVersion:'2026-10-15'};if(!connected){manual(pending);return;}submit.disabled=true;$('#enquiry-status').textContent='Sending your verification code…';try{await sendCode();}catch(e){error.hidden=false;error.textContent=e.message;}finally{submit.disabled=false;$('#enquiry-status').textContent='';}});
 $('#enquiry-code-form').addEventListener('submit',async e=>{e.preventDefault();if(!e.target.reportValidity())return;const button=e.target.querySelector('button');button.disabled=true;$('#verification-status').textContent='Checking your code…';try{const result=await api('/verify',{challengeId:challenge,code:$('#enquiry-code').value});if(result.submitted!==true||typeof result.reference!=='string'||(pending.discounts&&result.discountSignup!==true))throw Error('Submission or signup was not confirmed. Please contact the showroom.');$('#enquiry-verification').hidden=true;const box=$('#enquiry-result');box.replaceChildren();const h=document.createElement('h2');h.textContent='Your enquiry has been received.';const p=document.createElement('p');p.textContent='Reference: '+result.reference+(pending.discounts?' You’re signed up for discount information and cabinet planning updates.':'');box.append(h,p);box.hidden=false;clearInterval(timer);}catch(e){$('#verification-status').textContent=e.message;}finally{button.disabled=false;}});
 $('#enquiry-change-email').onclick=()=>{$('#enquiry-verification').hidden=true;form.hidden=false;challenge=null;clearInterval(timer);email.focus();};
 $('#enquiry-resend').onclick=async()=>{if(Date.now()<resendAt)return;$('#enquiry-resend').disabled=true;try{await sendCode();$('#verification-status').textContent='A new code was sent. Use the latest code.';}catch(e){$('#verification-status').textContent=e.message;cooldown(30);}};addEventListener('pagehide',()=>clearInterval(timer));
}
